DEFINE INSTRUMENT TAS_instrument(kI = 1.55, kF = 1.55, wVS = 0.03, tilt = 0, SA = -1, A3 = 0, A4 = 70, L3 = 1, L4 = 1, Mono_flatswitch = 0)

DECLARE
%{
  double m_n = 1.67493e-27;
  double hbar = 1.05457e-34;
  double meV_to_SI = 1.6022e-22;
  double SI_to_meV = 6.2414e+21;
  double MGUIDE = 3.2;
  double W_para = 0.0025;
  double R0_para = 0.99;
  double Qc_para = 0.0217;
  double alpha_para = 3.9;
  double LGUIDE_1 = 18.65;
  double LGUIDE_2 = 17.8;
  double rho_AV = 1.23;
  double L1 = 1.75;
  double L2 = 2.2;
  int SM = -1;
  int SS = +1;
  double DM = 3.355;
  double DA = 3.355;
%}

INITIALIZE
%{
  double A1, A2, RMH, RMV, A5, A6, RAH, RAV, lambdaI, EI, SelFreq, dlambdaI, l_min, l_max, e_min, e_max;
  double beta_guide_1, beta_guide_2, s_guide_1, s_guide_2;

  A1 = SM*M_PI/180*asin(M_PI/(DM*kI));
  A2 = 2*A1;
  RMH = (L1+L2)/(2*sin(A1*M_PI/180));
  if (Mono_flatswitch == 1) RMH = 0.0;
  RMV = (L1+L2)*sin(A1*M_PI/180);

  printf("monochromator angles are:\n A1=%7.3f, A2=%7.3f [deg]\n",A1,A2);
  printf("radius of curvature RMH=%7.3f [m]\nradius of curvature RMV=%7.3f [m] \n",RMH,RMV);

  printf("sample angles are:\n A3=%7.3f, A4=%7.3f [deg]\n",A3,A4);

  A5 = SA*M_PI/180*asin(M_PI/(DA*kF));
  A6 = 2*A5;
  RAH = (L3+L4)/(2*sin(A5*M_PI/180));
  RAV = SA*1/rho_AV;

  printf("analyser angles are:\n A5=%7.3f, A6=%7.3f [deg]\n",A5,A6);
  printf("radius of curvature RAH=%7.3f [m]\nradius of curvature RAV=%7.3f [m] \n",RAH,RAV);

  lambdaI = 2*M_PI/kI;
  EI = SI_to_meV*hbar*hbar*kI*kI*1e20/2/m_n;
  SelFreq = 3956.06/(lambdaI*(360/(19.7+(2.1*tilt)))*0.25);

  dlambdaI = (1.75004E-05*pow(lambdaI,6) - 5.13903E-04*pow(lambdaI,5) + 6.04404E-03*pow(lambdaI,4) - 3.66989E-02*pow(lambdaI,3) + 1.22399E-01*pow(lambdaI,2) - 2.19626E-01*lambdaI + 2.0E-01)*lambdaI;

  l_min = lambdaI-dlambdaI;
  l_max = lambdaI+dlambdaI;
  e_min = 81.81/l_max/l_max;
  e_max = 81.81/l_min/l_min;

  printf("velocity selector frequency is %7.3f [Hz]\n",SelFreq);
  printf("lambda=%7.3f [A]\nkI=%7.3f [A^-1] \nEI=%7.3f [meV]\n",lambdaI,kI,EI);
  printf("Maxwellian source forced to emit only between l_min=%7.3f and l_max=%7.3f [A] in order to save simulation time\n",l_min,l_max);
  printf("correspondingly, the energy monitors at sample position are detecting between %7.3f and %7.3f [meV]\n",e_min,e_max);

  beta_guide_1 = LGUIDE_1/2800*180/M_PI;
  beta_guide_2 = LGUIDE_2/2800*180/M_PI;
  s_guide_1 = 2800-sqrt(2800*2800-LGUIDE_1*LGUIDE_1);
  s_guide_2 = 2800-sqrt(2800*2800-LGUIDE_2*LGUIDE_2);
%}

TRACE

COMPONENT Origin = Progress_bar() AT (0, 0, 0) ABSOLUTE

COMPONENT Gen_Source = Source_gen(radius = 0.0775, dist = 1.53, focus_xw = 0.2, focus_yh = 0.125, I1 = 1e10, T1 = 45, Lmin = l_min, Lmax = l_max) AT (0, 0, 0) RELATIVE Origin ROTATED (0, 0, 0) RELATIVE Origin

COMPONENT NL1A_NL1B_NL2_NL3_InPile_Entrance_Window = Arm() AT (0, 0, 1.530) RELATIVE Origin

COMPONENT NL1A_NL1B_NL2_NL3_InPile = Guide(w1 = 0.170696, h1 = 0.129, w2 = 0.340522, h2 = 0.129, l = 1.870, R0 = R0_para, Qc = Qc_para, alpha = alpha_para, m = MGUIDE, W = W_para) AT (0, 0, 0) RELATIVE NL1A_NL1B_NL2_NL3_InPile_Entrance_Window

COMPONENT NL1B_Straight1_Entrance_Window = Arm() AT (-0.1277, 0, 3.405) RELATIVE Origin ROTATED (0, -2.15, 0) RELATIVE Origin

COMPONENT NL1B_Straight1 = Guide(w1 = 0.06, h1 = 0.125, w2 = 0.06, h2 = 0.125, l = 1.549, R0 = R0_para, Qc = Qc_para, alpha = alpha_para, m = MGUIDE, W = W_para) AT (0, 0, 0) RELATIVE NL1B_Straight1_Entrance_Window

COMPONENT NL1B_Curved_Entrance_Window = Arm() AT (0, 0, 1.549) RELATIVE NL1B_Straight1_Entrance_Window

COMPONENT NL1B_Curved_Guide_1 = Guide_curved(w1 = 0.06, h1 = 0.125, l = LGUIDE_1, R0 = R0_para, Qc = Qc_para, alpha = alpha_para, m = MGUIDE, W = W_para, curvature = 3920) AT (0, 0, 0) RELATIVE NL1B_Curved_Entrance_Window ROTATED (0, 0, 180) RELATIVE NL1B_Curved_Entrance_Window

COMPONENT NL1B_Velocity_Selector_Gap_Entrance_Window = Arm() AT (-s_guide_1, 0, LGUIDE_1) RELATIVE NL1B_Curved_Entrance_Window ROTATED (0, -beta_guide_1, 0) RELATIVE NL1B_Curved_Entrance_Window

COMPONENT Before_selec = PSD_monitor(nx = 50, ny = 50, filename = "PSD_monitor_before.dat", xwidth = 0.20, yheight = 0.20, restore_neutron = 1) AT (0, 0, 0.19) RELATIVE NL1B_Velocity_Selector_Gap_Entrance_Window

COMPONENT SELEC = Selector(xmin = -0.0625, xmax = 0.0625, ymin = -0.03, ymax = 0.03, length = 0.25, nslit = 72, d = 0.0004, radius = 0.123, alpha = 19.7, nu = SelFreq) AT (0, 0, 0.2) RELATIVE NL1B_Velocity_Selector_Gap_Entrance_Window ROTATED (0, tilt, 90) RELATIVE NL1B_Velocity_Selector_Gap_Entrance_Window

COMPONENT After_selec = PSD_monitor(nx = 50, ny = 50, filename = "PSD_monitor_after.dat", xwidth = 0.20, yheight = 0.20, restore_neutron = 1) AT (0, 0, 0.46) RELATIVE NL1B_Velocity_Selector_Gap_Entrance_Window

COMPONENT NL1B_Curved_2_Entrance_Window = Arm() AT (0, 0, 0.47) RELATIVE NL1B_Velocity_Selector_Gap_Entrance_Window

COMPONENT NL1B_Curved_Guide_2 = Guide_curved(w1 = 0.06, h1 = 0.125, l = LGUIDE_2, R0 = R0_para, Qc = Qc_para, alpha = alpha_para, m = MGUIDE, W = W_para, curvature = 2800) AT (0, 0, 0) RELATIVE NL1B_Curved_2_Entrance_Window ROTATED (0, 0, 180) RELATIVE NL1B_Curved_2_Entrance_Window

COMPONENT NL1B_Straight2_Entrance_Window = Arm() AT (-s_guide_2, 0, LGUIDE_2) RELATIVE NL1B_Curved_2_Entrance_Window ROTATED (0, -beta_guide_2, 0) RELATIVE NL1B_Curved_2_Entrance_Window

COMPONENT NL1B_Straight2 = Guide(w1 = 0.06, h1 = 0.125, w2 = 0.06, h2 = 0.125, l = 3.500, R0 = R0_para, Qc = Qc_para, alpha = alpha_para, m = MGUIDE, W = W_para) AT (0, 0, 0) RELATIVE NL1B_Straight2_Entrance_Window

COMPONENT NL1B_Elliptical_Entrance_Window = Arm() AT (0.0000, 0, 3.500) RELATIVE NL1B_Straight2_Entrance_Window ROTATED (0, 0.000, 0.00) RELATIVE NL1B_Straight2_Entrance_Window

COMPONENT elliptical_piece = Guide_tapering(option = "elliptical", w1 = 0.06, h1 = 0.125, l = 2.5, linw = 2.9, loutw = 0.4, R0 = 0.99, Qcx = 0.0217, Qcy = 0.0217, alphax = 4.00, alphay = alpha_para, W = 0.002, mx = 5.2, my = MGUIDE, segno = 800) AT (0, 0, 0) RELATIVE NL1B_Elliptical_Entrance_Window

COMPONENT Virtual_source = Slit(xwidth = wVS, yheight = 0.2) AT (0, 0, 2.900) RELATIVE NL1B_Elliptical_Entrance_Window

COMPONENT NL1B_Vertical_Guide_Entrance_Window = Arm() AT (0.0000, 0, 2.925) RELATIVE NL1B_Elliptical_Entrance_Window ROTATED (0, 0.000, 0.00) RELATIVE NL1B_Elliptical_Entrance_Window

COMPONENT NL1B_Vertical_Guide = Guide_channeled(w1 = 0.03, h1 = 0.125, w2 = 0.15, h2 = 0.125, l = 1.475, R0 = R0_para, nslit = 1, Qcx = Qc_para, Qcy = Qc_para, alphax = alpha_para, alphay = alpha_para, W = W_para, mx = 0, my = MGUIDE) AT (0, 0, 0) RELATIVE NL1B_Vertical_Guide_Entrance_Window

COMPONENT NL1B_Guide_Exit = Arm() AT (0, 0, 1.475) RELATIVE NL1B_Vertical_Guide_Entrance_Entrance_Window

COMPONENT energy_endguide = E_monitor(nE = 200, filename = "energy-endguide.dat", xwidth = 0.17, yheight = 0.135, Emin = e_min, Emax = e_max, restore_neutron = 1) AT (0, 0, 0) RELATIVE NL1B_Guide_Exit

COMPONENT Mono_center = Arm() AT (0, 0, 0.25) RELATIVE NL1B_Guide_Exit ROTATED (0, A1, 0) RELATIVE NL1B_Guide_Exit

COMPONENT Monochromator = Monochromator_curved(zwidth = 0.02, yheight = 0.02, gap = 0.0005, NH = 15, NV = 7, mosaich = 40, mosaicv = 40, r0 = 1.0, t0 = 0.00001, RV = RMV, RH = RMH) AT (0, 0, 0) RELATIVE Mono_center

COMPONENT Mono_sample_arm = Arm() AT (0, 0, 0) RELATIVE Mono_center ROTATED (0, A2, 0) RELATIVE NL1B_Guide_Exit

COMPONENT energy_mono = E_monitor(nE = 200, filename = "energy-mono.dat", xwidth = 0.2, yheight = 0.125, Emin = e_min, Emax = e_max, restore_neutron = 1) AT (0, 0, 0.15) RELATIVE Mono_sample_arm

COMPONENT energy_pre_sample = E_monitor(nE = 50, filename = "energy-pre-sample.dat", xwidth = 0.08, yheight = 0.08, Emin = e_min, Emax = e_max, restore_neutron = 1) AT (0, 0, L2-0.1) RELATIVE Mono_sample_arm

COMPONENT Sample_center = Arm() AT (0, 0, L2) RELATIVE Mono_sample_arm ROTATED (0, A3, 0) RELATIVE Mono_sample_arm

COMPONENT Sample_analyser_arm = Arm() AT (0, 0, 0) RELATIVE Sample_center ROTATED (0, A4, 0) RELATIVE Mono_sample_arm

COMPONENT div_mono = Divergence_monitor(nh = 20, nv = 20, filename = "div-sample.dat", xwidth = 0.1, yheight = 0.1, maxdiv_h = 4, maxdiv_v = 4, restore_neutron = 1) AT (0, 0, L2-0.05) RELATIVE Mono_sample_arm

COMPONENT div_mono_H = Div1D_monitor(ndiv = 35, filename = "H-div-sample.dat", xwidth = 0.005, yheight = 0.7, maxdiv = 4, restore_neutron = 1) AT (0, 0, L2-0.04) RELATIVE Mono_sample_arm

COMPONENT psd_sam = PSD_monitor(nx = 60, ny = 60, filename = "psd-sam.dat", xwidth = 0.20, yheight = 0.20, restore_neutron = 1) AT (0, 0, 0) RELATIVE Sample_center ROTATED (0, 0, 0) RELATIVE Mono_sample_arm

COMPONENT dpsd1 = PSDlin_monitor(nbins = 30, filename = "linpsdsam.dat", xmin = -0.1, xmax = 0.1, ymin = -0.1, ymax = 0.1) AT (0, 0, 0) RELATIVE Sample_center ROTATED (0, 0, 0) RELATIVE Mono_sample_arm

END
